// Code node "Finished ids" in ops-cost-collector (mode: run once for all items).
// Input: pages of GET /api/v1/executions (pagination on), each {data, nextCursor}.
// Also reads the pages of "List workflows" to know which workflows contain a model node.
//
// Output: ONE item {ids, no_llm, listed}
//   ids     finished executions of workflows WITH a model node: their data gets downloaded
//   no_llm  finished executions of workflows without one: marked scanned with 0 calls
//           straight from the listing, no download. On a live instance that is most of them
//           (error handler, chaos, schedulers), so the backlog clears 10x faster.
// A workflow is judged by its current version: an LLM node removed later means its old
// runs aren't counted (decision 032).
// Running executions are already left out by the API; waiting ones are left for later.
const FINISHED = new Set(['success', 'error', 'crashed', 'canceled']);
const MODEL_NODE = /\.lm[A-Z]|lmChat/;   // @n8n/n8n-nodes-langchain.lmChatAnthropic, .lmOpenAi, ...

let workflowPages = [];
try { workflowPages = $('List workflows').all(); } catch (e) { workflowPages = []; }
const llmWorkflows = new Set();
for (const page of workflowPages) {
  for (const wf of page.json?.data ?? []) {
    if ((wf.nodes ?? []).some((n) => MODEL_NODE.test(String(n.type ?? '')))) llmWorkflows.add(String(wf.id));
  }
}
// No workflow list at all (API change, permissions): download everything rather than miss costs.
const knowsWorkflows = workflowPages.some((p) => Array.isArray(p.json?.data));

const ids = new Set();
const noLlm = new Map();
let listed = 0;
for (const page of $input.all()) {
  for (const e of page.json?.data ?? []) {
    listed++;
    if (e?.id == null || !FINISHED.has(e.status)) continue;
    const id = String(e.id);
    if (!knowsWorkflows || llmWorkflows.has(String(e.workflowId))) ids.add(id);
    else noLlm.set(id, {
      execution_id: id,
      workflow_id: String(e.workflowId ?? ''),
      execution_status: e.status,
      started_at: e.startedAt ?? e.createdAt,
    });
  }
}
return [{ json: { ids: [...ids], no_llm: [...noLlm.values()], listed } }];

// Code node "Extract LLM calls" in ops-cost-collector (mode: run once for all items).
// Each input item is one execution from GET /api/v1/executions/{id}?includeData=true.
// Output: ONE item {executions: [...], calls: [...]} for record-llm-usage.sql.
//
// Where the numbers come from (n8n 2.42.5, @n8n/ai-utilities n8n-llm-tracing.ts):
// every model sub-node (Anthropic Chat Model, Groq Chat Model, ...) writes one run per
// LLM call with data.ai_languageModel[0][0].json = { response, tokenUsage } — or
// tokenUsageEstimate when the provider reported nothing (streaming). The chain node
// above it repeats the same totals in metadata.tracing; it is NOT counted, or every
// call would be counted twice.
// The model id is in the run's inputOverride (options.model), which is what was really
// sent; the node parameter can be an expression.

const FINISHED = new Set(['success', 'error', 'crashed', 'canceled']);

// Node type → provider name used in model_prices.
const PROVIDERS = {
  lmChatAnthropic: 'anthropic',
  lmChatGroq: 'groq',
  lmChatOpenAi: 'openai',
  lmOpenAi: 'openai',
  lmChatAzureOpenAi: 'azure-openai',
  lmChatGoogleGemini: 'google',
  lmChatGoogleVertex: 'google-vertex',
  lmChatMistralCloud: 'mistral',
  lmChatDeepSeek: 'deepseek',
  lmChatOpenRouter: 'openrouter',
  lmChatXAiGrok: 'xai',
  lmChatAwsBedrock: 'bedrock',
  lmChatOllama: 'ollama',
  lmChatCohere: 'cohere',
};

function providerOf(nodeType) {
  const short = String(nodeType ?? '').split('.').pop();
  return PROVIDERS[short] ?? (short.replace(/^lm(Chat)?/, '').toLowerCase() || 'unknown');
}

function modelOf(run, node) {
  const opts = run.inputOverride?.ai_languageModel?.[0]?.[0]?.json?.options ?? {};
  let m = opts.model ?? opts.modelName ?? opts.model_name ?? opts.model_id;
  if (!m) {
    const p = node?.parameters?.model;
    m = p && typeof p === 'object' ? p.value : p;
  }
  if (typeof m !== 'string' || m === '' || m.startsWith('=')) return 'unknown';
  return m.replace(/^models\//, '');
}

const int = (v) => {
  const n = Math.round(Number(v));
  return Number.isFinite(n) && n > 0 ? n : 0;
};

const executions = [];
const calls = [];
const skipped = [];

for (const item of $input.all()) {
  const e = item.json ?? {};
  const id = e.id != null ? String(e.id) : null;
  if (!id) continue;
  // Not finished yet (waiting, running): leave it for a later run instead of marking it scanned.
  if (!FINISHED.has(e.status)) { skipped.push({ id, reason: `status ${e.status}` }); continue; }
  // Over EXECUTIONS_DATA_MAX_DISPLAY_SIZE without ignoreDataSizeLimit, or redacted:
  // no data means we can't know. Skip it rather than record "no LLM calls".
  const runData = e.data?.resultData?.runData;
  if (!runData) { skipped.push({ id, reason: 'no execution data' }); continue; }

  const wf = e.workflowData ?? {};
  const nodesByName = Object.fromEntries((wf.nodes ?? []).map((n) => [n.name, n]));
  const startedAt = e.startedAt ?? e.createdAt;
  let found = 0;

  for (const [nodeName, runs] of Object.entries(runData)) {
    (runs ?? []).forEach((run, runIndex) => {
      const out = run?.data?.ai_languageModel?.[0]?.[0]?.json;
      if (!out) return;                               // not a model node, or the call failed
      const usage = out.tokenUsage ?? out.tokenUsageEstimate;
      if (!usage) return;
      const node = nodesByName[nodeName];
      calls.push({
        execution_id: id,
        workflow_id: String(e.workflowId ?? wf.id ?? ''),
        workflow_name: wf.name ?? null,
        node_name: nodeName,
        run_index: runIndex,
        provider: providerOf(node?.type),
        model: modelOf(run, node),
        // Anthropic: n8n folds cache reads and writes into promptTokens, so they can't be
        // priced separately (decision 030).
        input_tokens: int(usage.promptTokens),
        output_tokens: int(usage.completionTokens),
        estimated: !out.tokenUsage,
        execution_status: e.status,
        started_at: startedAt,
      });
      found++;
    });
  }

  executions.push({
    execution_id: id,
    workflow_id: String(e.workflowId ?? wf.id ?? ''),
    workflow_name: wf.name ?? null,
    execution_status: e.status,
    started_at: startedAt,
    llm_calls: found,
  });
}

return [{ json: { executions, calls, skipped } }];

// Code node "Build budget alert" in ops-cost-collector (mode: run once for each item).
// Input: one row from check-budget.sql. Output: {text} for Telegram, HTML parse mode.
const r = $json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const usd = (v) => {
  if (v === null || v === undefined || v === '') return 'no price';
  const n = Number(v);
  if (!Number.isFinite(n)) return 'no price';
  return n >= 0.01 ? `$${n.toFixed(2)}` : `$${n.toFixed(5)}`;
};

const lines = [
  `💸 <b>LLM budget exceeded</b> · ${esc(r.day)} (UTC)`,
  `Spent ${usd(r.spent)} of ${usd(r.threshold)} today: ${r.calls} calls in ${r.runs} runs.`,
];
const top = Array.isArray(r.workflows) ? r.workflows : [];
if (top.length) {
  lines.push('', 'Top workflows:');
  for (const w of top) lines.push(`• ${esc(w.workflow_name || '(unnamed)')}: ${usd(w.cost)} in ${w.runs} runs`);
}
if (Number(r.unpriced) > 0) {
  lines.push('', `⚠️ ${r.unpriced} calls have no price yet, so real spend is higher.`);
}
lines.push('', 'One message per day. The dashboard shows each run.');
return { json: { text: lines.join('\n'), day: r.day, kind: r.kind } };
